import{y as t,b as o,c as n,X as r}from"./chunks/vue.Bn9cO5I3.js";import"./app.tjc9Wtrh.js";import"./chunks/mermaid.DvhSlOLG.js";const m=JSON.parse('{"title":"ADR-015: Immutable Audit Ledger Design","description":"","frontmatter":{},"headers":[],"relativePath":"reference/ADR-015-immutable-audit-ledger.md","filePath":"reference/ADR-015-immutable-audit-ledger.md","lastUpdated":1771558125000}'),i={name:"reference/ADR-015-immutable-audit-ledger.md"};function a(d,e,c,s,l,h){return o(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="adr-015-immutable-audit-ledger-design" tabindex="-1">ADR-015: Immutable Audit Ledger Design <a class="header-anchor" href="#adr-015-immutable-audit-ledger-design" aria-label="Permalink to &quot;ADR-015: Immutable Audit Ledger Design&quot;">​</a></h1><p>undefined<strong>Status:</strong> Accepted undefined<strong>Date:</strong> 2026-02-19 undefined<strong>Authors:</strong> agent-f1 undefined<strong>Deciders:</strong> thegent architecture team</p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The <code>thegent</code> platform orchestrates multiple AI agents performing autonomous actions — file writes, shell commands, API calls, planning cycles — on behalf of users. Without a tamper-evident audit trail, it is impossible to:</p><ol><li>Detect post-hoc modification or deletion of agent action records.</li><li>Reconstruct the exact sequence of events in an AgilePlus governance cycle for forensic replay.</li><li>Satisfy enterprise compliance requirements that demand non-repudiation of automated actions.</li><li>Provide evidence to governance policy engine (<code>qa-policy-engine.sh</code>) that actions occurred as reported.</li></ol><p>The system already logs agent activity to JSONL files under <code>.thegent/sessions/</code>. The gap is that these files are mutable plain text — any process (or adversary) with filesystem access can silently alter or truncate them without detection.</p><p>Two overlapping ledger implementations exist:</p><ul><li>undefined<strong><code>EvidenceLedger</code></strong> (<code>src/thegent/governance/evidence_ledger.py</code>): Per-AgilePlus-cycle evidence events; used heavily throughout <code>agileplus.py</code>.</li><li>undefined<strong><code>IncidentLedger</code></strong> / <strong><code>LedgerVerifier</code></strong> (<code>src/thegent/governance/ledger.py</code>): General incident / artifact records used by governance policy enforcement.</li></ul><p>Both independently apply SHA-256 hash chaining. This ADR documents and ratifies the shared design pattern, and designates <code>EvidenceLedger</code> as the canonical reference implementation.</p><hr><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Audit records are stored in <strong>append-only JSONL files with SHA-256 hash chaining</strong>. Each entry in the ledger contains:</p><ol><li>undefined<strong><code>event_type</code></strong> — semantic label for the event (e.g., <code>cycle_started</code>, <code>task_dispatched</code>, <code>verification_completed</code>).</li><li>undefined<strong><code>timestamp</code></strong> — ISO-8601 UTC timestamp.</li><li>undefined<strong><code>cycle_id</code></strong> — correlation identifier for the governing AgilePlus cycle.</li><li>undefined<strong><code>payload</code></strong> — event-specific structured data (dict).</li><li>undefined<strong><code>prev_hash</code></strong> — SHA-256 hash of the immediately preceding record (<code>null</code> for the genesis record).</li><li>undefined<strong><code>hash</code></strong> — SHA-256 hash of this record&#39;s canonical JSON representation (computed over all fields except <code>hash</code> itself, with keys sorted, no whitespace).</li></ol><p>The first record in every new ledger file is a <strong>schema version marker</strong> with <code>event: &quot;schema_version&quot;</code> and <code>version: 1</code>, which anchors the chain.</p><h3 id="hash-calculation" tabindex="-1">Hash Calculation <a class="header-anchor" href="#hash-calculation" aria-label="Permalink to &quot;Hash Calculation&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>canonical_json = json.dumps({k: v for k, v in record.items() if k != &quot;hash&quot;},</span></span>
<span class="line"><span>                             sort_keys=True, separators=(&quot;,&quot;, &quot;:&quot;))</span></span>
<span class="line"><span>record[&quot;hash&quot;] = sha256(canonical_json.encode()).hexdigest()</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="chain-verification" tabindex="-1">Chain Verification <a class="header-anchor" href="#chain-verification" aria-label="Permalink to &quot;Chain Verification&quot;">​</a></h3><p>To verify integrity, iterate all records in order:</p><ol><li>Recompute the expected hash from the record&#39;s fields (excluding <code>hash</code>).</li><li>Assert <code>record[&quot;hash&quot;] == expected_hash</code>. Any mismatch indicates the record was altered.</li><li>Assert <code>record[&quot;prev_hash&quot;] == hash_of_previous_record</code>. Any mismatch indicates a record was inserted, deleted, or reordered.</li></ol><p>A <code>verify_chain()</code> method on <code>EvidenceLedger</code> provides this in O(n) time with O(1) memory.</p><h3 id="file-layout" tabindex="-1">File Layout <a class="header-anchor" href="#file-layout" aria-label="Permalink to &quot;File Layout&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.thegent/sessions/agileplus/evidence_ledger.jsonl   # EvidenceLedger</span></span>
<span class="line"><span>.thegent/sessions/&lt;custom-path&gt;/incident.jsonl       # IncidentLedger (governance / omega-safety)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Files are opened in append mode (<code>&quot;a&quot;</code>) exclusively. No record is ever overwritten or deleted by normal operation.</p><hr><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li>undefined<strong>Tamper detection</strong>: Any modification (insert, delete, or edit) to any record in the chain is detectable by replaying <code>verify_chain()</code>.</li><li>undefined<strong>Portability</strong>: Plain JSONL files require no database, broker, or network service. They are readable with standard Unix tools (<code>jq</code>, <code>rg</code>) and trivially transferable.</li><li>undefined<strong>No external dependency</strong>: The implementation uses only Python stdlib (<code>hashlib</code>, <code>json</code>, <code>pathlib</code>) plus <code>pydantic</code> (already a core project dependency).</li><li>undefined<strong>Forensic replay</strong>: Because events contain <code>cycle_id</code> and full payloads, any AgilePlus cycle can be reconstructed entirely from the ledger without consulting live state.</li><li>undefined<strong>Streaming-friendly</strong>: Records are appended one at a time. No full-file rewrites are needed; ledgers survive incomplete writes (the corrupt tail line is detectable via <code>verify_chain()</code>).</li><li>undefined<strong>Queryable</strong>: <code>EvidenceLedger.query(cycle_id=..., event_type=...)</code> supports lightweight in-process filtering without a query engine.</li></ul><h3 id="negative-trade-offs" tabindex="-1">Negative / Trade-offs <a class="header-anchor" href="#negative-trade-offs" aria-label="Permalink to &quot;Negative / Trade-offs&quot;">​</a></h3><ul><li>undefined<strong>O(n) verification cost</strong>: Full chain verification scales linearly with ledger size. For very long-running systems accumulating millions of records, periodic archival and re-anchoring is required (not yet implemented; see Open Questions).</li><li>undefined<strong>No concurrent writers</strong>: The <code>open(&quot;a&quot;)</code> pattern is safe for a single writer per file on POSIX filesystems, but concurrent multi-process writers to the same file path require external locking. Current usage is single-writer per session directory.</li><li>undefined<strong>No encryption</strong>: Hashing provides integrity but not confidentiality. Payloads containing sensitive data (agent outputs, tool call arguments) are stored in plaintext.</li><li>undefined<strong>No remote replication</strong>: If the local filesystem is fully compromised (including the ledger), the chain cannot self-prove its own integrity without an external anchor (e.g., a periodic hash published to a remote store). This is out of scope for the current implementation.</li><li>undefined<strong>Rolling hash variant divergence</strong>: <code>IncidentLedger</code> in <code>ledger.py</code> uses a slightly different serialization strategy (string concatenation splitting on <code>,&quot;rolling_hash&quot;</code> vs. the <code>sort_keys</code> JSON approach in <code>EvidenceLedger</code>). Both are functionally correct but are not cross-verifiable. Future work should unify on <code>EvidenceLedger</code>&#39;s approach.</li></ul><hr><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><h3 id="_1-sqlite-with-write-ahead-log-wal" tabindex="-1">1. SQLite with Write-Ahead Log (WAL) <a class="header-anchor" href="#_1-sqlite-with-write-ahead-log-wal" aria-label="Permalink to &quot;1. SQLite with Write-Ahead Log (WAL)&quot;">​</a></h3><p>undefined<strong>Rejected.</strong> SQLite files are mutable; records can be <code>UPDATE</code>d or <code>DELETE</code>d silently. WAL provides crash recovery, not tamper evidence. Adding a separate integrity check layer would recreate the hash-chaining logic on top of SQLite anyway, with added complexity and a binary file format opaque to standard tools.</p><h3 id="_2-append-only-s3-object-storage" tabindex="-1">2. Append-only S3 / Object Storage <a class="header-anchor" href="#_2-append-only-s3-object-storage" aria-label="Permalink to &quot;2. Append-only S3 / Object Storage&quot;">​</a></h3><p>undefined<strong>Rejected for local dev.</strong> Requiring an S3-compatible store as a runtime dependency for local development and single-user deployments is a disproportionate operational burden. S3 Object Lock provides immutability guarantees, but only for cloud-hosted deployments. The JSONL approach is portable across local and cloud; a future egress adapter could mirror to S3 without changing the core format.</p><h3 id="_3-opentelemetry-spans" tabindex="-1">3. OpenTelemetry Spans <a class="header-anchor" href="#_3-opentelemetry-spans" aria-label="Permalink to &quot;3. OpenTelemetry Spans&quot;">​</a></h3><p>undefined<strong>Rejected.</strong> OTEL spans are designed for distributed tracing and observability, not tamper-evident audit. OTEL exporters (OTLP, Jaeger, Zipkin) can drop, sample, or batch records. The collector is an additional runtime service. Hash chaining is not part of the OTEL data model. OTEL remains appropriate for performance observability; it is complementary, not a replacement.</p><h3 id="_4-write-once-filesystem-flags-e-g-chattr-a" tabindex="-1">4. Write-once filesystem flags (e.g., <code>chattr +a</code>) <a class="header-anchor" href="#_4-write-once-filesystem-flags-e-g-chattr-a" aria-label="Permalink to &quot;4. Write-once filesystem flags (e.g., \`chattr +a\`)&quot;">​</a></h3><p>undefined<strong>Rejected.</strong> Filesystem-level append-only flags require elevated privileges to set and are platform-specific (Linux <code>ext4</code>/<code>xfs</code>; not available on macOS <code>HFS+</code>/<code>APFS</code> in the same form). They also do not detect tampering of already-appended content — only prevent deletion or overwriting. Cross-platform portability is a hard requirement for <code>thegent</code>.</p><h3 id="_5-signed-jwt-hmac-per-record-symmetric-key" tabindex="-1">5. Signed JWT / HMAC per-record (symmetric key) <a class="header-anchor" href="#_5-signed-jwt-hmac-per-record-symmetric-key" aria-label="Permalink to &quot;5. Signed JWT / HMAC per-record (symmetric key)&quot;">​</a></h3><p>undefined<strong>Considered but deferred.</strong> Per-record HMAC with a shared secret would make ledger records independently verifiable without replaying the chain. The cost is key management: the secret must be stored separately from the ledger, or the scheme is circular. SHA-256 hash chaining without a key is sufficient for the current threat model (filesystem access by unauthorized processes, not a malicious insider who also controls the verification process). HMAC signing is noted as a future enhancement.</p><hr><h2 id="implementation-reference" tabindex="-1">Implementation Reference <a class="header-anchor" href="#implementation-reference" aria-label="Permalink to &quot;Implementation Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>EvidenceLedger</code> (canonical)</td><td><code>src/thegent/governance/evidence_ledger.py</code></td><td>AgilePlus cycle evidence; <code>record()</code>, <code>query()</code>, <code>verify_chain()</code></td></tr><tr><td><code>EvidenceEvent</code> (Pydantic model)</td><td><code>src/thegent/governance/evidence_ledger.py</code></td><td>Schema for each ledger entry</td></tr><tr><td><code>IncidentLedger</code></td><td><code>src/thegent/governance/ledger.py</code></td><td>Governance/omega-safety incident records; <code>record_artifact()</code>, <code>verify_integrity()</code></td></tr><tr><td><code>LedgerVerifier</code></td><td><code>src/thegent/governance/ledger.py</code></td><td>Standalone chain verification for arbitrary ledger paths</td></tr><tr><td><code>AgilePlusRunner</code></td><td><code>src/thegent/governance/agileplus.py</code></td><td>Primary consumer of <code>EvidenceLedger</code>; records all cycle lifecycle events</td></tr><tr><td><code>omega_safety</code></td><td><code>src/thegent/verification/omega_safety.py</code></td><td>References <code>evidence_ledger</code> for safety gate evidence</td></tr><tr><td><code>artifacts/api.py</code></td><td><code>src/thegent/artifacts/api.py</code></td><td>Uses <code>verify_hash_chain()</code> for artifact integrity at ingest</td></tr></tbody></table><h3 id="event-types-recorded-by-evidenceledger" tabindex="-1">Event Types Recorded by EvidenceLedger <a class="header-anchor" href="#event-types-recorded-by-evidenceledger" aria-label="Permalink to &quot;Event Types Recorded by EvidenceLedger&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Constant</th><th>Value</th><th>When Emitted</th></tr></thead><tbody><tr><td><code>CYCLE_STARTED</code></td><td><code>&quot;cycle_started&quot;</code></td><td>AgilePlus cycle begins</td></tr><tr><td><code>SCAN_COMPLETED</code></td><td><code>&quot;scan_completed&quot;</code></td><td>Work stream scan finishes</td></tr><tr><td><code>PLAN_CREATED</code></td><td><code>&quot;plan_created&quot;</code></td><td>Planning phase produces a plan</td></tr><tr><td><code>TASK_DISPATCHED</code></td><td><code>&quot;task_dispatched&quot;</code></td><td>Task sent to an agent</td></tr><tr><td><code>TASK_COMPLETED</code></td><td><code>&quot;task_completed&quot;</code></td><td>Agent reports task completion</td></tr><tr><td><code>VERIFICATION_COMPLETED</code></td><td><code>&quot;verification_completed&quot;</code></td><td>Verification gate passes/fails</td></tr><tr><td><code>CYCLE_COMPLETED</code></td><td><code>&quot;cycle_completed&quot;</code></td><td>Full AgilePlus cycle finishes</td></tr></tbody></table><hr><h2 id="open-questions" tabindex="-1">Open Questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open Questions&quot;">​</a></h2><ol><li>undefined<strong>Archival and re-anchoring strategy</strong>: For long-running deployments, the ledger will grow unbounded. A roll-over protocol is needed: close the current ledger, publish its final hash as the genesis <code>prev_hash</code> of a new ledger file, and archive the old file.</li><li>undefined<strong>Unification of <code>EvidenceLedger</code> and <code>IncidentLedger</code></strong>: The two implementations should be merged or made cross-verifiable. The canonical approach (<code>sort_keys</code> JSON + excluding <code>hash</code> field) from <code>EvidenceLedger</code> should be adopted in <code>IncidentLedger</code>.</li><li>undefined<strong>HMAC signing</strong>: Future enhancement to add per-record HMAC signatures for independent record verification without full chain replay.</li><li>undefined<strong>Remote anchor</strong>: Periodic publication of the chain head hash to a remote, append-only store (e.g., S3 with Object Lock, or a public blockchain commitment) would defeat adversaries with full local filesystem access.</li><li>undefined<strong>Concurrent writer safety</strong>: If multiple processes must write to the same ledger (e.g., in a multi-agent swarm), a file-level lock (via <code>fcntl.flock</code> or a <code>LockFile</code> wrapper using <code>filelock</code>) must be added before <code>record()</code> calls.</li></ol><hr><h2 id="cross-references" tabindex="-1">Cross-References <a class="header-anchor" href="#cross-references" aria-label="Permalink to &quot;Cross-References&quot;">​</a></h2><ul><li><code>ADR.md</code> — Master ADR index</li><li><code>src/thegent/governance/evidence_ledger.py</code> — Canonical implementation</li><li><code>src/thegent/governance/ledger.py</code> — Incident ledger implementation</li><li><code>src/thegent/governance/agileplus.py</code> — Primary consumer</li><li><code>docs/reference/WORK_STREAM.md</code> — Work stream item <code>adr-015-immutable-ledger</code></li></ul>`,53)])])}const f=t(i,[["render",a]]);export{m as __pageData,f as default};
